-- Changes to the team's data model diagram for the pipeline (Phase 9).
-- Safe to run more than once.

-- 1. New tables ------------------------------------------------------------

-- ItemLink: Every Related tab: links between key insights, strategic risks, follow-up questions and metrics; read from either end.
IF OBJECT_ID(N'ItemLink', N'U') IS NULL
CREATE TABLE [ItemLink] (
	[ItemLinkId] INTEGER NOT NULL IDENTITY, 
	[CompanyId] INTEGER NOT NULL, 
	[FromType] NVARCHAR(20) NOT NULL, 
	[FromId] INTEGER NOT NULL, 
	[ToType] NVARCHAR(20) NOT NULL, 
	[ToId] INTEGER NOT NULL, 
	[LinkSource] NVARCHAR(16) NULL, 
	PRIMARY KEY ([ItemLinkId]), 
	FOREIGN KEY([CompanyId]) REFERENCES [Company] ([CompanyId])
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_ItemLink_from' AND object_id = OBJECT_ID(N'ItemLink'))
    CREATE INDEX [ix_ItemLink_from] ON [ItemLink] ([CompanyId], [FromType], [FromId]);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_ItemLink_to' AND object_id = OBJECT_ID(N'ItemLink'))
    CREATE INDEX [ix_ItemLink_to] ON [ItemLink] ([CompanyId], [ToType], [ToId]);
GO

-- CompanyMetricDetail: Metric modal (and the Loan Portfolio modal as metric 'loan_portfolio'): methodology, data sources, data points, UW relevance.
IF OBJECT_ID(N'CompanyMetricDetail', N'U') IS NULL
CREATE TABLE [CompanyMetricDetail] (
	[CompanyMetricDetailId] INTEGER NOT NULL IDENTITY, 
	[CompanyId] INTEGER NOT NULL, 
	metric_id INTEGER NOT NULL, 
	[Methodology] NVARCHAR(max) NULL, 
	[DataSources] NVARCHAR(max) NULL, 
	[DataPoints] NVARCHAR(max) NULL, 
	[UnderwritingRelevance] NVARCHAR(max) NULL, 
	[UpdatedAt] DATETIME NULL, 
	PRIMARY KEY ([CompanyMetricDetailId]), 
	FOREIGN KEY([CompanyId]) REFERENCES [Company] ([CompanyId]), 
	FOREIGN KEY(metric_id) REFERENCES metrics (metric_id)
);
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = N'ix_CompanyMetricDetail_company_metric' AND object_id = OBJECT_ID(N'CompanyMetricDetail'))
    CREATE INDEX [ix_CompanyMetricDetail_company_metric] ON [CompanyMetricDetail] ([CompanyId], metric_id);
GO

-- pipeline_publish_map: Pipeline bookkeeping (pipeline object -> app id); written and read only by the pipeline.
IF OBJECT_ID(N'pipeline_publish_map', N'U') IS NULL
CREATE TABLE pipeline_publish_map (
	entity NVARCHAR(40) NOT NULL, 
	pipeline_key NVARCHAR(200) NOT NULL, 
	app_id INTEGER NOT NULL, 
	row_hash NVARCHAR(64) NOT NULL, 
	published_at DATETIMEOFFSET NOT NULL, 
	PRIMARY KEY (entity, pipeline_key)
);
GO

